'use strict';
/* Geografia Irada — modelos 3D embutidos (GLB em base64). Gerado por ferramentas/gerar-modelos.mjs; não edite à mão.
   Origem e licenças: ferramentas/modelos/catalogo.json (Kenney, CC0 1.0, e modelos próprios, CC0 1.0).
   Uso: new THREE.GLTFLoader().parse(Modelos3D.buffer('arvore-folhosa'), '', gltf => cena.add(gltf.scene)). */
const Modelos3D = (() => {
  const B64 = {
    'ambulancia': '',
    'arvore-folhosa': '',
    'arvore-savana': '',
    'aviao': '',
    'bandeira': '',
    'barreira': '',
    'bomba-petroleo': '',
    'cacto': '',
    'caixa': '',
    'caminhao-ajuda': '',
    'carga-ajuda': '',
    'conteiner-azul': '',
    'conteiner-verde': '',
    'conteiner-vermelho': '',
    'coracao': '',
    'escavadeira': '',
    'escola': '',
    'estrela': '',
    'fabrica': '',
    'foguete': '',
    'guindaste-porto': '',
    'hospital': '',
    'jazida': '',
    'moeda': '',
    'muro': '',
    'navio-cargueiro': '',
    'navio-granel': '',
    'nuvem': '',
    'painel-solar': '',
    'palmeira-curva': '',
    'palmeira': '',
    'pinguim': '',
    'pinheiro-neve': '',
    'pinheiro': '',
    'plataforma-petroleo': '',
    'podio': '',
    'pomba': '',
    'predio-governo': '',
    'satelite': '',
    'tanque-combustivel': '',
    'tenda': '',
    'termeletrica': '',
    'torre-resfriamento': '',
    'trofeu': '',
    'turbina-eolica': '',
    'urso-polar': '',
    'usina-nuclear': '',
  };
  const buffer = id => Uint8Array.from(atob(B64[id]), c => c.charCodeAt(0)).buffer;
  return { ids: Object.keys(B64), buffer };
})();
